"description": "暴击率提升<strong>{{num:critical-rate|percent}}</strong>，暴击伤害提升<strong>{{num:critical-damage|percent}}</strong>。每有<strong>1%</strong>移动速度加成，武器射击和爆炸伤害分别提升<strong>{{num:weapon-hit-per-speed|percent}}</strong>和<strong>{{num:weapon-explode-per-speed|percent}}</strong>，最多分别提升<strong>{{num:weapon-hit-damage|percent}}</strong>和<strong>{{num:weapon-explode-damage|percent}}</strong>。暴击命中后，自身移动速度提升<strong>{{num:movement-speed|percent}}</strong>，持续<strong>2</strong>秒，可刷新。"
"description_override": true
"preview_change": "new"
num_modifier_values:
  critical-rate: { row: "lc:111051029_1_0", field: base }
  critical-damage: { row: "lc:111051029_1_1", field: base }
  weapon-hit-damage: { row: "lc:111051030_1_0", field: coefficient }
  weapon-explode-damage: { row: "lc:111051030_1_1", field: coefficient }
  weapon-hit-per-speed: { row: "lc:111051030_1_0", field: coefficient, scale: 0.02 }
  weapon-explode-per-speed: { row: "lc:111051030_1_1", field: coefficient, scale: 0.02 }
  movement-speed: { row: "lc:111051031_1_0", field: base }
effect_values:
  - label: "暴击率"
    stages:
      - value: { ref: critical-rate, format: signed-percent }
  - label: "暴击伤害"
    stages:
      - value: { ref: critical-damage, format: signed-percent }
  - label: "武器射击伤害"
    stages:
      - condition: "每1%移动速度加成"
        value: { ref: weapon-hit-per-speed, format: signed-percent }
      - condition: "移动速度加成达到50%时"
        value: { ref: weapon-hit-damage, format: signed-percent }
  - label: "武器爆炸伤害"
    stages:
      - condition: "每1%移动速度加成"
        value: { ref: weapon-explode-per-speed, format: signed-percent }
      - condition: "移动速度加成达到50%时"
        value: { ref: weapon-explode-damage, format: signed-percent }
  - label: "移动速度"
    stages:
      - condition: "暴击命中后持续2秒，可刷新"
        value: { ref: movement-speed, format: signed-percent }
